/* @lc app=leetcode id=2074 lang=kotlin */
class Solution { fun reverseEvenLengthGroups(head: ListNode?): ListNode? = generateSequence(head) { it.next }.toList().let { nodes -> (1..2000).asSequence().scan(0 to 0) { (s, _), i -> (s + i) to i }.takeWhile { it.first - it.second < nodes.size }.map { (s, l) -> (s - l) to minOf(l, nodes.size - (s - l)) }.map { (st, len) -> if (len % 2 == 0) nodes.subList(st, st + len).reversed() else nodes.subList(st, st + len) }.flatten().toList().let { res -> res.also { it.forEachIndexed { i, n -> n.next = it.getOrNull(i + 1) } }.firstOrNull() } } }